<div class="headline"><div><h1>Inscripciones</h1><p class="subtitle">Controla qué participantes están inscritos en cada evento.</p></div><a class="btn" href="<?= h(url('inscripcion_form')) ?>">+ Nueva inscripción</a></div>
            <section class="panel"><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Participante</th><th>Fecha de registro</th><th>Acciones</th></tr></thead><tbody>
            <?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['evento']) ?></strong><div class="muted"><?= h($r['evento_fecha']) ?></div></td><td><?= h($r['participante']) ?><div class="muted"><?= h($r['email']) ?></div></td><td><?= h($r['fecha_inscripcion']) ?></td><td><div class="buttons"><a class="btn btn-light btn-sm" href="<?= h(url('inscripcion_form', ['id'=>$r['inscripcion_id']])) ?>">Editar</a><form method="post" data-confirm="¿Eliminar esta inscripción?"><input type="hidden" name="action" value="delete_inscripcion"><input type="hidden" name="id" value="<?= (int)$r['inscripcion_id'] ?>"><?= csrf_field() ?><button class="btn btn-danger btn-sm">Eliminar</button></form></div></td></tr><?php endforeach; ?>
            <?php if (!$rows): ?><tr><td class="empty" colspan="4">Todavía no hay inscripciones registradas.</td></tr><?php endif; ?></tbody></table></div></section>
